using UnityEngine;
using Newtonsoft.Json.Linq;
namespace IslandGame {
 // Explicit developer view; fixed reusable line buffers, no colliders or mesh baking.
 public sealed class BossContactDebug:System.IDisposable {
  readonly GameObject root;readonly LineRenderer[] lines=new LineRenderer[14];readonly Vector3[] points=new Vector3[49];readonly Material material;
  readonly UnityEngine.UI.Text label;bool touchLatch;
  public bool Visible;public int AttackId {get;private set;}public float AttackPhase {get;private set;}
  public BossContactDebug(Transform parent){BossContactProfile.Load();root=new GameObject("Contact debug · F8");root.transform.SetParent(parent,false);material=new Material(Shader.Find("Sprites/Default"));for(int i=0;i<lines.Length;i++){var go=new GameObject("Contact "+i);go.layer=30;go.transform.SetParent(root.transform,false);var line=go.AddComponent<LineRenderer>();line.sharedMaterial=material;line.positionCount=49;line.widthMultiplier=.022f;line.useWorldSpace=true;line.shadowCastingMode=UnityEngine.Rendering.ShadowCastingMode.Off;line.receiveShadows=false;lines[i]=line;}var overlay=new GameObject("Attack ID and contact clock",typeof(RectTransform),typeof(Canvas),typeof(UnityEngine.UI.CanvasScaler));overlay.transform.SetParent(root.transform,false);var canvas=overlay.GetComponent<Canvas>();canvas.renderMode=RenderMode.ScreenSpaceOverlay;canvas.sortingOrder=100;var scaler=overlay.GetComponent<UnityEngine.UI.CanvasScaler>();scaler.uiScaleMode=UnityEngine.UI.CanvasScaler.ScaleMode.ScaleWithScreenSize;scaler.referenceResolution=new Vector2(1080,2340);var textObject=new GameObject("Contact status",typeof(RectTransform),typeof(UnityEngine.UI.Text));textObject.transform.SetParent(overlay.transform,false);var rect=(RectTransform)textObject.transform;rect.anchorMin=new Vector2(.03f,.88f);rect.anchorMax=new Vector2(.97f,.94f);rect.offsetMin=rect.offsetMax=Vector2.zero;label=textObject.GetComponent<UnityEngine.UI.Text>();label.font=Resources.Load<Font>("Fonts/NotoSansCJKkr-Regular");label.fontSize=25;label.color=Color.white;label.alignment=TextAnchor.MiddleCenter;label.raycastTarget=false;root.SetActive(false);}
  void Ring(int index,Vector3 center,float radius,Color color,int axis=0){for(int i=0;i<49;i++){float a=i*Mathf.PI*2/48;var p=new Vector3(Mathf.Cos(a)*radius,0,Mathf.Sin(a)*radius);if(axis==1)p=new Vector3(p.x,p.z,0);points[i]=center+p;}lines[index].SetPositions(points);lines[index].startColor=lines[index].endColor=color;}
  public void Update(JObject state,float time,Transform boss,Transform hero,Vector3 rightElbow,Vector3 rightHand,Vector3 leftElbow,Vector3 leftHand,Vector3 weaponBase=default,Vector3 weaponTip=default,int heroAttack=0,float heroPhase=0,bool heroActive=false,string viewState=""){bool threeTouches=Input.touchCount>=3;if(Input.GetKeyDown(KeyCode.F8)||threeTouches&&!touchLatch)Visible=!Visible;touchLatch=threeTouches;root.SetActive(Visible&&boss&&hero);if(!root.activeSelf)return;var b=BossContactProfile.Boss(state);var m=b?["motion"] as JObject;AttackId=(int?)m?["attackId"]??0;AttackPhase=m==null?0:(time-NativeCombatPresentation.N(m["start"]))/Mathf.Max(.001f,NativeCombatPresentation.N(m["duration"]));bool combo=(string)m?["kind"]=="boss-combo";
   Ring(0,boss.position+Vector3.up*.04f,BossContactProfile.BodyRadius,Color.yellow);Ring(1,hero.position+Vector3.up*.05f,BossContactProfile.HeroRadius,Color.cyan);
   float height=((string)state["hero"]?["action"]??"").StartsWith("sliding")?.65f:BossContactProfile.HeroHeight,r=BossContactProfile.HeroRadius;
   var lower=hero.position+Vector3.up*r;var upper=hero.position+Vector3.up*(height-r);
   Capsule(2,lower,upper,r,Vector3.right,Color.cyan);Capsule(9,lower,upper,r,Vector3.forward,Color.cyan);
   for(int h=0;h<2;h++){var a=h==0?rightElbow:leftElbow;var z=h==0?rightHand:leftHand;var side=Vector3.Cross((z-a).normalized,Vector3.up);if(side.sqrMagnitude<.001f)side=Vector3.right;var color=combo&&BossContactProfile.Active(AttackPhase,h)?Color.red:Color.green;
    Capsule(5+h,a,z,.30f,side.normalized,color);Ring(3+h,z,BossContactProfile.HandRadii[h],color,1);Ring(7+h,z,BossContactProfile.HandRadii[h],color);}
   lines[10].enabled=false;int hitId=0;float hitAt=-100;foreach(var f in state["fx"] as JArray??Empty)if((string)f["kind"]=="boss-hook"&&time>=NativeCombatPresentation.N(f["contactAt"])&&time-NativeCombatPresentation.N(f["contactAt"])<.3f){hitId=(int?)f["attackId"]??0;hitAt=NativeCombatPresentation.N(f["contactAt"]);var p=f["point"];if(p!=null){lines[10].enabled=true;Ring(10,new Vector3(NativeCombatPresentation.N(p["x"])/100,NativeCombatPresentation.N(p["y"])/100,(NativeCombatPresentation.N(p["z"])-5000)/100),.12f,Color.white,1);}}
   Capsule(11,weaponBase,weaponTip,.06f,Vector3.right,heroActive?Color.red:Color.green);
   Capsule(12,boss.position+Vector3.up*1.4f,boss.position+Vector3.up*5.1f,1.4f,Vector3.right,new Color(1,.4f,1));
   Capsule(13,boss.position+Vector3.up*1.4f,boss.position+Vector3.up*5.1f,1.4f,Vector3.forward,new Color(1,.4f,1));
   label.text=viewState+" · Hero #"+heroAttack+" / "+heroPhase.ToString("F3")+"\n공격 #"+AttackId+" · phase "+AttackPhase.ToString("F3")+" · clock "+time.ToString("F3")+"\n"+(hitId>0?"접촉 #"+hitId+" @ "+hitAt.ToString("F3"):"노랑: 몸체 · 청록: Hurtbox · 빨강: 유효 공격");

  }
  void Capsule(int index,Vector3 a,Vector3 b,float radius,Vector3 side,Color color){var axis=(b-a).normalized;if(axis.sqrMagnitude<.001f)axis=Vector3.up;for(int i=0;i<=24;i++){float angle=i*Mathf.PI/24;points[i]=b+radius*(side*Mathf.Cos(angle)+axis*Mathf.Sin(angle));}for(int i=1;i<=24;i++){float angle=Mathf.PI+i*Mathf.PI/24;points[24+i]=a+radius*(side*Mathf.Cos(angle)+axis*Mathf.Sin(angle));}lines[index].loop=true;lines[index].SetPositions(points);lines[index].startColor=lines[index].endColor=color;}
  static readonly JArray Empty=new JArray();
  public void Dispose(){UnityEngine.Object.Destroy(root);UnityEngine.Object.Destroy(material);}
 }
}
